    /// The rows pinning the scanner window.
    fn build_window_rows() -> Vec<CuratedRow> {
        let letters_254 = "a".repeat(254);
        let letters_255 = "a".repeat(255);
        let digits_253 = "1".repeat(253);
        vec![
            // 256 letters: the window holds 255 units, the next scan starts at the 256th.
            build_row(
                "window_cuts_a_long_word_at_255_units",
                "a".repeat(256),
                &[(letters_255.as_str(), 0, 255, AlphaNum), ("a", 255, 256, AlphaNum)],
            ),
            // 254 letters and U+1D49C (ALetter, two units): the pair would end at unit 256.
            build_row(
                "window_never_splits_a_surrogate_pair",
                format!("{letters_254}\u{1D49C}"),
                &[
                    (letters_254.as_str(), 0, 254, AlphaNum),
                    ("\u{1D49C}", 254, 256, AlphaNum),
                ],
            ),
            // `.` (MidNumLet) is unit 255 and needs a letter after it inside the window; it is
            // then dropped.
            build_row(
                "window_ends_before_a_mid_letter_at_the_boundary",
                format!("{letters_254}.b"),
                &[(letters_254.as_str(), 0, 254, AlphaNum), ("b", 255, 256, AlphaNum)],
            ),
            // U+0301 (Extend) is unit 255, inside the window.
            build_row(
                "window_keeps_a_combining_mark_ending_at_the_boundary",
                format!("{letters_254}\u{0301}b"),
                &[
                    (format!("{letters_254}\u{0301}").as_str(), 0, 255, AlphaNum),
                    ("b", 255, 256, AlphaNum),
                ],
            ),
            // U+0301 is unit 256: outside the window, and an Extend character starts no token.
            build_row(
                "window_drops_a_combining_mark_past_the_boundary",
                format!("{letters_255}\u{0301}"),
                &[(letters_255.as_str(), 0, 255, AlphaNum)],
            ),
            // 253 digits, `,` (MidNum) and `0` fill the window at unit 255.
            build_row(
                "window_cuts_a_number_group_inside",
                format!("{digits_253},000"),
                &[(format!("{digits_253},0").as_str(), 0, 255, Num), ("00", 255, 257, Num)],
            ),
        ]
    }

    /// The rows pinning Unicode 12.1 segmentation, spaces and format characters.
    fn build_unicode_version_rows() -> Vec<CuratedRow> {
        vec![
            // U+A7C7 was assigned in Unicode 13.0: Word_Break=Other at 12.1.
            build_row(
                "post_12_1_letter_splits_the_word",
                "ab\u{A7C7}cd",
                &[("ab", 0, 2, AlphaNum), ("cd", 3, 5, AlphaNum)],
            ),
            // U+1ABF was assigned in Unicode 13.0.
            build_row(
                "post_12_1_mark_splits_the_word",
                "ab\u{1ABF}cd",
                &[("ab", 0, 2, AlphaNum), ("cd", 3, 5, AlphaNum)],
            ),
            // U+11F50 (Kawi digit zero) was assigned in Unicode 15.0; it is two units long.
            build_row(
                "post_12_1_digit_splits_the_number",
                "12\u{11F50}34",
                &[("12", 0, 2, Num), ("34", 4, 6, Num)],
            ),
            // U+30000 (CJK Extension G) was assigned in Unicode 13.0: no Han script at 12.1.
            build_row(
                "post_12_1_ideograph_is_dropped",
                "a\u{30000}b",
                &[("a", 0, 1, AlphaNum), ("b", 3, 4, AlphaNum)],
            ),
            // emoji-data 12.1 lists the reserved range 1FA96..1FFFD as Extended_Pictographic.
            build_row(
                "reserved_extended_pictographic_is_emoji",
                "1\u{1FBF0}2 \u{1FA96}",
                &[
                    ("1", 0, 1, Num),
                    ("\u{1FBF0}", 1, 3, Emoji),
                    ("2", 3, 4, Num),
                    ("\u{1FA96}", 5, 7, Emoji),
                ],
            ),
            // U+202F is Word_Break=ExtendNumLet.
            build_row(
                "narrow_no_break_space_joins_words",
                "a\u{202F}b",
                &[("a\u{202F}b", 0, 3, AlphaNum)],
            ),
            // NBSP and ZWSP are Other, EN/THIN/OGHAM spaces WSegSpace, CR LF and U+2028 line breaks.
            build_row(
                "other_spaces_and_line_breaks_split_words",
                "a\u{00A0}b\u{2002}c\u{2009}d\u{1680}e\u{200B}f\ng\r\nh\u{2028}i",
                &[
                    ("a", 0, 1, AlphaNum),
                    ("b", 2, 3, AlphaNum),
                    ("c", 4, 5, AlphaNum),
                    ("d", 6, 7, AlphaNum),
                    ("e", 8, 9, AlphaNum),
                    ("f", 10, 11, AlphaNum),
                    ("g", 12, 13, AlphaNum),
                    ("h", 15, 16, AlphaNum),
                    ("i", 17, 18, AlphaNum),
                ],
            ),
            // U+2060, U+FEFF and U+00AD are Format, U+200C Extend, U+200D ZWJ; a Format character starts no token.
            build_row(
                "format_and_extend_characters_stay_in_the_token",
                "a\u{2060}b c\u{FEFF}d e\u{00AD}f g\u{200C}h i\u{200D}j \u{00AD}ab",
                &[
                    ("a\u{2060}b", 0, 3, AlphaNum),
                    ("c\u{FEFF}d", 4, 7, AlphaNum),
                    ("e\u{00AD}f", 8, 11, AlphaNum),
                    ("g\u{200C}h", 12, 15, AlphaNum),
                    ("i\u{200D}j", 16, 19, AlphaNum),
                    ("ab", 21, 23, AlphaNum),
                ],
            ),
        ]
    }

    /// The rows pinning code points with no line in the Unicode 12.1 `WordBreakProperty.txt`, which
    /// makes them `Word_Break=Other`. `LineBreak.txt`, `Scripts.txt` and `emoji-data.txt` give them
    /// nothing that starts a token either, so each one breaks on both sides and is dropped.
    fn build_word_break_other_rows() -> Vec<CuratedRow> {
        vec![
            build_row(
                "extra_high_tone_bar_splits_the_word",
                "a\u{02E5}b",
                &[("a", 0, 1, AlphaNum), ("b", 2, 3, AlphaNum)],
            ),
            build_row(
                "armenian_apostrophe_splits_the_word",
                "a\u{055A}b",
                &[("a", 0, 1, AlphaNum), ("b", 2, 3, AlphaNum)],
            ),
            build_row(
                "armenian_abbreviation_mark_splits_the_word",
                "a\u{055F}b",
                &[("a", 0, 1, AlphaNum), ("b", 2, 3, AlphaNum)],
            ),
            build_row(
                "armenian_hyphen_splits_the_word",
                "a\u{058A}b",
                &[("a", 0, 1, AlphaNum), ("b", 2, 3, AlphaNum)],
            ),
            build_row(
                "extra_high_dotted_tone_bar_splits_the_word",
                "a\u{A708}b",
                &[("a", 0, 1, AlphaNum), ("b", 2, 3, AlphaNum)],
            ),
        ]
    }

    /// The rows pinning emoji sequences and emoji ties.
    fn build_emoji_rows() -> Vec<CuratedRow> {
        vec![
            build_row(
                "emoji_zwj_sequence",
                "\u{1F469}\u{200D}\u{1F4BB}",
                &[("\u{1F469}\u{200D}\u{1F4BB}", 0, 5, Emoji)],
            ),
            build_row(
                "emoji_modifier_sequence",
                "\u{1F44D}\u{1F3FD}",
                &[("\u{1F44D}\u{1F3FD}", 0, 4, Emoji)],
            ),
            // U+1F3FD is Emoji_Modifier (and Word_Break=Extend).
            build_row("lone_skin_tone_is_emoji", "\u{1F3FD}", &[("\u{1F3FD}", 0, 2, Emoji)]),
            // The modifier is Extend, so the letter rule takes it: two code points beat the one-character emoji.
            build_row(
                "letter_with_skin_tone_is_alphanum",
                "a\u{1F3FD}",
                &[("a\u{1F3FD}", 0, 3, AlphaNum)],
            ),
            build_row(
                "leading_zwj_joins_the_emoji",
                "\u{200D}\u{1F600}",
                &[("\u{200D}\u{1F600}", 0, 3, Emoji)],
            ),
            // A regional indicator only forms a token in a pair.
            build_row(
                "regional_indicators_pair_and_a_lone_or_third_one_is_dropped",
                "\u{1F1FA} \u{1F1FA}\u{1F1F8}\u{1F1EB}",
                &[("\u{1F1FA}\u{1F1F8}", 3, 7, Emoji)],
            ),
            build_row(
                "emoji_tag_sequence",
                "\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}",
                &[(
                    "\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}",
                    0,
                    14,
                    Emoji,
                )],
            ),
            // U+FE0E is not part of an emoji sequence, so it is left as a dropped Extend character.
            build_row(
                "text_and_emoji_presentation_selectors",
                "\u{2764}\u{FE0E} \u{2764}\u{FE0F}",
                &[("\u{2764}", 0, 1, Emoji), ("\u{2764}\u{FE0F}", 3, 5, Emoji)],
            ),
            build_row(
                "keycaps_and_a_hash_before_a_digit",
                "1\u{FE0F}\u{20E3} #\u{20E3} #1",
                &[
                    ("1\u{FE0F}\u{20E3}", 0, 3, Emoji),
                    ("#\u{20E3}", 4, 6, Emoji),
                    ("1", 8, 9, Num),
                ],
            ),
            build_row(
                "copyright_registered_trade_mark_wavy_dash_and_part_alternation_mark_are_emoji",
                "\u{00A9} \u{00AE} \u{2122} \u{3030}\u{303D}",
                &[
                    ("\u{00A9}", 0, 1, Emoji),
                    ("\u{00AE}", 2, 3, Emoji),
                    ("\u{2122}", 4, 5, Emoji),
                    ("\u{3030}", 6, 7, Emoji),
                    ("\u{303D}", 7, 8, Emoji),
                ],
            ),
            // U+24C2 is ALetter and Extended_Pictographic; it lowercases to U+24DC.
            build_row(
                "emoji_wins_a_tie_and_is_lowercased_while_a_longer_word_wins",
                "\u{24C2} \u{24C2}x",
                &[("\u{24DC}", 0, 1, Emoji), ("\u{24DC}x", 2, 4, AlphaNum)],
            ),
        ]
    }

    /// The rows pinning lowercasing and the letter classes that decide a token's type.
    fn build_lowercase_and_letter_class_rows() -> Vec<CuratedRow> {
        vec![
            build_row(
                "simple_lowercase_mapping",
                "\u{0130} \u{03A3}\u{0391}\u{03A3} \u{03F9} \u{1E9E} \u{212A} \u{212B} \u{2126} \u{13A0} \u{01C5} \u{023A}\u{023E}\u{2C62}",
                &[
                    ("i", 0, 1, AlphaNum),
                    ("\u{03C3}\u{03B1}\u{03C3}", 2, 5, AlphaNum),
                    ("\u{03F2}", 6, 7, AlphaNum),
                    ("\u{00DF}", 8, 9, AlphaNum),
                    ("k", 10, 11, AlphaNum),
                    ("\u{00E5}", 12, 13, AlphaNum),
                    ("\u{03C9}", 14, 15, AlphaNum),
                    ("\u{AB70}", 16, 17, AlphaNum),
                    ("\u{01C6}", 18, 19, AlphaNum),
                    ("\u{2C65}\u{2C66}\u{026B}", 20, 23, AlphaNum),
                ],
            ),
            // U+3005 is ALetter and Han (the word rule comes first); U+3006 is Other, Common; U+3007 is Other, Han.
            build_row(
                "iteration_mark_closing_mark_and_number_zero",
                "\u{3005} \u{3006} \u{3007}",
                &[("\u{3005}", 0, 1, AlphaNum), ("\u{3007}", 4, 5, Ideographic)],
            ),
            // U+30FC is Word_Break=Katakana, script Common.
            build_row(
                "prolonged_sound_mark_after_hiragana_is_katakana",
                "\u{3042}\u{30FC}",
                &[("\u{3042}", 0, 1, Hiragana), ("\u{30FC}", 1, 2, Katakana)],
            ),
            // Tangut and Nushu ideographs are Word_Break=Other and not Han.
            build_row("tangut_and_nushu_are_dropped", "\u{17000}\u{1B170}", &[]),
        ]
    }

    /// The rows pinning numbers, words and punctuation mixed in one text.
    fn build_mixed_text_rows() -> Vec<CuratedRow> {
        vec![
            build_row(
                "number_followed_by_letters_is_alphanum",
                "1.5e-3",
                &[("1.5e", 0, 4, AlphaNum), ("3", 5, 6, Num)],
            ),
            // `-` is Other, `:` MidLetter (it never joins digits), `.` MidNumLet; a letter after
            // digits continues a word.
            build_row(
                "iso_timestamp",
                "2026-10-08T12:34:56.789Z",
                &[
                    ("2026", 0, 4, Num),
                    ("10", 5, 7, Num),
                    ("08t12", 8, 13, AlphaNum),
                    ("34", 14, 16, Num),
                    ("56.789z", 17, 24, AlphaNum),
                ],
            ),
            build_row(
                "underscores_around_digits_are_num",
                "_123 123_",
                &[("_123", 0, 4, Num), ("123_", 5, 9, Num)],
            ),
            build_row(
                "email_splits_at_the_at_sign",
                "user@example.com",
                &[("user", 0, 4, AlphaNum), ("example.com", 5, 16, AlphaNum)],
            ),
            build_row(
                "url_splits_at_slashes_and_the_colon_before_them",
                "https://x.io/a",
                &[
                    ("https", 0, 5, AlphaNum),
                    ("x.io", 8, 12, AlphaNum),
                    ("a", 13, 14, AlphaNum),
                ],
            ),
            build_row(
                "apostrophes_stay_inside_words",
                "don't O'Neil's",
                &[("don't", 0, 5, AlphaNum), ("o'neil's", 6, 14, AlphaNum)],
            ),
            // Hebrew_Letter followed by Double_Quote and Hebrew_Letter, and by Single_Quote.
            build_row(
                "hebrew_letters_with_quotes",
                "\u{05D0}\"\u{05D1} \u{05D0}'",
                &[("\u{05D0}\"\u{05D1}", 0, 3, AlphaNum), ("\u{05D0}'", 4, 6, AlphaNum)],
            ),
            build_row(
                "dotted_underscored_and_colon_joined_words",
                "v1.2 192.168.0.1 trace_id level:error 12:30 e-mail",
                &[
                    ("v1.2", 0, 4, AlphaNum),
                    ("192.168.0.1", 5, 16, Num),
                    ("trace_id", 17, 25, AlphaNum),
                    ("level:error", 26, 37, AlphaNum),
                    ("12", 38, 40, Num),
                    ("30", 41, 43, Num),
                    ("e", 44, 45, AlphaNum),
                    ("mail", 46, 50, AlphaNum),
                ],
            ),
        ]
    }

    /// The rows yielding no token.
    fn build_no_token_rows() -> Vec<CuratedRow> {
        vec![
            build_row("no_token_in_an_empty_text", "", &[]),
            build_row("no_token_in_whitespace", " \t\r\n", &[]),
            build_row("no_token_in_punctuation_and_underscores", "!!! --- __", &[]),
            build_row("no_token_from_a_lone_combining_mark", "\u{0301}", &[]),
        ]
    }

