    #[test]
    fn the_curated_table_yields_the_stated_tokens() {
        let mismatches: Vec<String> = build_curated_rows()
            .into_iter()
            .filter_map(|row| {
                let actual_tokens = tokenize_with_utf16_offsets(&row.input);
                (actual_tokens != row.expected_tokens).then(|| {
                    format!(
                        "{}: expected {:?}, got {actual_tokens:?}",
                        row.name, row.expected_tokens
                    )
                })
            })
            .collect();
        assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
    }

    #[test]
    fn every_rule_and_token_class_names_rows_of_the_curated_table() {
        let rows = build_curated_rows();
        let row_names: BTreeSet<&str> = rows.iter().map(|row| row.name).collect();
        assert_eq!(row_names.len(), rows.len(), "row names are unique");
        let mut covered_row_names = BTreeSet::new();
        for &(rule, names) in COVERAGE {
            assert!(!names.is_empty(), "{rule} names no row");
            for name in names {
                assert!(row_names.contains(name), "{rule} names the missing row {name}");
                covered_row_names.insert(*name);
            }
        }
        let uncovered_row_names: Vec<&str> = row_names.difference(&covered_row_names).copied().collect();
        assert!(
            uncovered_row_names.is_empty(),
            "rows outside the coverage list: {uncovered_row_names:?}"
        );
        let types = [
            ("type ALPHANUM", AlphaNum),
            ("type NUM", Num),
            ("type SOUTHEAST_ASIAN", SoutheastAsian),
            ("type IDEOGRAPHIC", Ideographic),
            ("type HIRAGANA", Hiragana),
            ("type KATAKANA", Katakana),
            ("type HANGUL", Hangul),
            ("type EMOJI", Emoji),
        ];
        for (rule, kind) in types {
            let names = COVERAGE
                .iter()
                .find(|(listed_rule, _)| *listed_rule == rule)
                .map(|(_, names)| *names)
                .unwrap_or_default();
            assert!(!names.is_empty(), "{rule} is listed");
            for name in names {
                let row = rows.iter().find(|row| row.name == *name).expect("listed row exists");
                assert!(
                    row.expected_tokens.iter().any(|token| token.kind == kind),
                    "{name} is listed under {rule} but expects no such token"
                );
            }
        }
    }

    /// Code points the generator favours: window boundaries, post-12.1 code points, format and
    /// extend characters, emoji sequence parts and characters of every token class.
    const INTERESTING_CODE_POINTS: &[u32] = &[
        0x0020, 0x002E, 0x002C, 0x0027, 0x0022, 0x005F, 0x002D, 0x003A, 0x0023, 0x0031, 0x0061, 0x0041, 0x00AD, 0x0301,
        0x05D0, 0x0E2A, 0x0E31, 0x200B, 0x200C, 0x200D, 0x2060, 0x202F, 0x20E3, 0x3005, 0x3042, 0x30AB, 0x30FC, 0x4E2D,
        0xA7C7, 0xD55C, 0xFE0E, 0xFE0F, 0xFEFF, 0x1_1F50, 0x1ABF, 0x1_D49C, 0x1_F1FA, 0x1_F1F8, 0x1_F3FD, 0x1_F44D,
        0x1_F600, 0x1_FA96, 0x1_FBF0, 0x3_0000, 0xE_0067, 0xE_007F,
    ];

    /// Draws one text from `random_generator`, weighted to the code points the invariants risk.
    fn generate_text(random_generator: &mut StdRng) -> String {
        let mut text = String::new();
        for _ in 0..random_generator.random_range(0..12) {
            match random_generator.random_range(0..4) {
                // A run long enough to cross the scanner window.
                0 => {
                    let letter = if random_generator.random_bool(0.5) {
                        'a'
                    } else {
                        '\u{1D49C}'
                    };
                    for _ in 0..random_generator.random_range(120..140) {
                        text.push(letter);
                    }
                }
                1 => {
                    for _ in 0..random_generator.random_range(1..8) {
                        let index = random_generator.random_range(0..INTERESTING_CODE_POINTS.len());
                        text.extend(char::from_u32(INTERESTING_CODE_POINTS[index]));
                    }
                }
                _ => {
                    for _ in 0..random_generator.random_range(1..8) {
                        text.extend(char::from_u32(random_generator.random_range(0..=0x10_FFFF)));
                    }
                }
            }
        }
        text
    }

    #[test]
    fn generated_text_keeps_offsets_positions_and_lengths_within_the_invariants() {
        let mut random_generator = StdRng::seed_from_u64(0x5EED_0A1A);
        let mut token_count = 0;
        let mut longest_token_units = 0;
        for _ in 0..2_000 {
            let text = generate_text(&mut random_generator);
            let tokens = tokenize_standard(&text);
            token_count += tokens.len();
            let mut previous_end = 0;
            for (index, token) in tokens.iter().enumerate() {
                assert!(
                    token.start < token.end && token.end <= text.len(),
                    "{text:?}: {token:?}"
                );
                assert!(token.start >= previous_end, "{text:?}: tokens overlap at {token:?}");
                assert!(
                    text.is_char_boundary(token.start) && text.is_char_boundary(token.end),
                    "{text:?}: {token:?} splits a code point"
                );
                let slice = &text[token.start..token.end];
                let token_units = slice.encode_utf16().count();
                assert!(token_units <= 255, "{text:?}: {token:?} is too long");
                longest_token_units = longest_token_units.max(token_units);
                assert_eq!(usize::try_from(token.position).ok(), Some(index), "{text:?}: positions");
                assert_eq!(token.text.chars().count(), slice.chars().count(), "{text:?}: {token:?}");
                previous_end = token.end;
            }
        }
        assert!(token_count > 0, "the generated texts yield tokens");
        assert_eq!(longest_token_units, 255, "the seed reaches the scanner window");
    }

    #[test]
    fn normalize_lowercases_per_code_point_including_post_12_1_cased_letters() {
        // Expected values: UnicodeData.txt 16.0.0, field 13 of each capital.
        let cases = [
            ("Foo-BAR baz", "foo-bar baz"),
            ("\u{0130}", "i"),
            ("\u{03A3}\u{03A3}", "\u{03C3}\u{03C3}"),
            ("\u{A7C7}", "\u{A7C8}"),
            ("\u{A7C9}", "\u{A7CA}"),
            ("\u{2C2F}", "\u{2C5F}"),
            ("\u{10570}", "\u{10597}"),
            ("\u{1C89}", "\u{1C8A}"),
            ("\u{A7CB}", "\u{0264}"),
            ("\u{A7DC}", "\u{019B}"),
            ("\u{10D50}", "\u{10D70}"),
            ("\u{1D49C}", "\u{1D49C}"),
        ];
        for (input, expected_text) in cases {
            assert_eq!(normalize_standard(input), expected_text, "{input:?}");
        }
    }
